import { schoolInfoPlanSource, type ContentSource } from "@/data/sources";

/**
 * Written content for a 행정동×과목 page (/region/[province]/[city]/[dong]/[subject]) — the dong-level
 * counterpart of schoolSubjectContent.ts, using the same published-content pattern.
 *
 * - Facts come only from the official disclosures of the schools in that 행정동 (학교알리미 4-가
 *   교과별(학년별) 교수·학습 및 평가계획, 2026년 3차 공시 = 2026학년도 2학기). Each figure was read in the
 *   school's own attachment; nothing about 난이도·교육열·성적·학원 수 is stated.
 * - src/lib/dongContent.ts uses an entry (status "published" with notes) in place of the generated
 *   school-list text; without one the page keeps the generated content. The quality gate grades
 *   whichever text the page renders.
 * - The plans are per semester. Every entry records the term it was read from in `planTerm`; when the
 *   2027학년도 1학기 plans are disclosed (2027년 1차 공시, 4월) re-check each entry and update it or set
 *   status "draft" (docs/qa/uijeongbu-dong-subject-*.md list the schools and files used).
 */
export interface DongSubjectContent {
  citySlug: string;
  dongSlug: string;
  subjectSlug: string;
  status: "draft" | "published";
  /** 공시 학기 the facts were read from: "2026-2" = 2026학년도 2학기 (학교알리미 2026년 3차·9월 공시). */
  planTerm: "2026-2";
  intro: string;
  notes: { title: string; body: string }[];
  /** Official pages actually opened for the facts above; listed before the generated NEIS/행정구역 sources. */
  sources: ContentSource[];
}

